// zip the search items with their enriched deep-intel (1:1 by order), score,
// tag HOT/WATCH/SKIP, keep the ones worth opening, sorted best-first.
const search = $('Split jobs').all();
const deep = $input.all();
const num = v => (v==null||v===''||isNaN(+v)) ? null : +v;
const out = [];
for (let i=0;i<deep.length;i++){
  const s = (search[i]||{}).json || {};
  const j = (deep[i].json.job) || {};
  const bid = j.bid_stats || {};
  const cr = j.client_record || {};
  const spend = num(cr.spend_total);
  const prop = num(s.proposal_count) || 0;
  const hired = (j.job_activity && j.job_activity.totalHired) || 0;
  const spendScore = spend!=null ? Math.min(1, Math.log10(spend+1)/6) : 0.2;
  const compScore = 1 - Math.min(1, prop/50);
  const openScore = hired>0 ? 0.2 : 1;
  const payScore = bid.avg!=null ? Math.min(1, bid.avg/120) : 0.4;
  const score = Math.round(100*(0.34*spendScore+0.28*compScore+0.20*openScore+0.18*payScore));
  const tag = score>=72 ? 'HOT' : score>=55 ? 'WATCH' : 'SKIP';
  out.push({ json: {
    score, tag,
    title: s.title || j.title,
    type: s.job_type,
    proposals: prop,
    bid_avg: bid.avg, bid_min: bid.min, bid_max: bid.max,
    client_spend: spend,
    client_country: (s.client||{}).country,
    verified: (s.client||{}).verification_status === 'VERIFIED',
    connects_cost: num(j.connects_cost),
    id: s.id
  }});
}
out.sort((a,b)=> b.json.score - a.json.score);
return out;
